\title{An Irrationality Engine and Effective Bracketing\\ for the Euler--Mascheroni Constant}
\author{Aristotle}
\date{2026-06-24}

\begin{document}
\maketitle

\begin{abstract}
We develop a complete \emph{Diophantine engine} for irrationality---the equivalence between irrationality of a real number $x$ and the existence of arbitrarily small nonzero integer linear forms $q\,x - p$---and apply it as a diagnostic to the Euler--Mascheroni constant $\gamma = \lim_{n\to\infty}(H_n - \ln n)$. We prove the engine in three formulations: a biconditional $\varepsilon$-form, its two constituent directions (sufficiency via the nonzero-integer floor; necessity via Dirichlet's approximation theorem), and a sequence form suited to Ap\'ery-style arguments. We then quantify the standard approximations to $\gamma$. Writing $s_n = H_n - \ln(n+1)$ and $s'_n = H_n - \ln n$, we establish the exact trapping-width identity $s'_n - s_n = \ln(n+1) - \ln n = \ln(1 + 1/n)$ for $n \geq 1$, and derive effective one-sided and two-sided error bounds $|s_n - \gamma| < \ln(1 + 1/n)$. The combination isolates, in precise terms, the structural obstruction to an elementary irrationality proof of $\gamma$: the natural approximants converge only at rate $\Theta(1/n)$ (sub-geometric) and have \emph{transcendental} endpoints, hence cannot supply the integer data the engine requires. We close with five precise, testable conjectures. The mathematical content corresponds to a machine-checked Lean~4 development with no unproven assumptions.
\end{abstract}

\section{Introduction}

The Euler--Mascheroni constant
\[
\gamma \;=\; \lim_{n\to\infty}\Bigl(\sum_{k=1}^{n}\tfrac{1}{k} - \ln n\Bigr) \;\approx\; 0.5772156649,
\]
is among the most fundamental constants in analysis and number theory, yet its arithmetic nature is entirely unresolved: it is not known whether $\gamma$ is irrational, let alone transcendental. This contrasts with $e$ (irrationality: Euler; transcendence: Hermite) and $\zeta(3)$ (irrationality: Ap\'ery, 1978).

This paper has two aims. First, we give a self-contained, rigorous treatment of the abstract criterion underlying essentially all irrationality proofs---the \emph{irrationality engine}---including a faithful biconditional and a sequence form. Second, we apply the engine \emph{diagnostically} to $\gamma$: rather than claiming a proof of an open problem, we quantify the best elementary approximations and prove precisely why they cannot drive the engine.

Throughout, $H_n = \sum_{k=1}^n 1/k$ is the $n$-th harmonic number, $\ln$ the natural logarithm, $\lfloor \cdot \rfloor$ the floor, and $\round(t)$ the nearest integer to $t$.

\subsection{Summary of contributions}
\begin{itemize}
  \item \textbf{Theorem A} (engine, sequence form): if $x$ admits integers $q_n \geq 1$, $p_n$ with $q_n x - p_n \neq 0$ and $q_n x - p_n \to 0$, then $x$ is irrational.
  \item \textbf{Theorem B} (engine, $\varepsilon$-form, sufficiency).
  \item \textbf{Theorem C} (engine, $\varepsilon$-form, necessity, via Dirichlet); hence a biconditional.
  \item \textbf{Theorem D} (exact bracket width): $s'_n - s_n = \ln(n+1) - \ln n$ for $n \geq 1$.
  \item \textbf{Theorems E--G} (effective error bounds).
\end{itemize}
All statements correspond to machine-checked theorems with no \texttt{sorry} and only standard foundational axioms.

\subsection{Relation to classical irrationality proofs}
The engine of Section~3 is the explicit, reusable distillate of a method two and a half centuries old. Euler's proof that $e$ is irrational constructs $q_n = n!$, $p_n = n!\sum_{k=0}^n 1/k!$, for which $q_n e - p_n = n!\sum_{k>n} 1/k! \in (0,1)$ and tends to $0$; Theorem~\ref{thm:A} concludes irrationality at once. Ap\'ery's 1978 result for $\zeta(3)$ produces integer sequences $a_n,b_n$ with $b_n\zeta(3) - a_n \neq 0$ decaying geometrically; the logical step is again Theorem~\ref{thm:A}. What changes per constant is never the engine but the difficulty of manufacturing the integer fuel. We do \emph{not} claim $\gamma$ irrational; we prove the engine in full and sharp effective facts showing the standard approximants cannot drive it.

\section{Definitions}

\begin{definition}[Harmonic number]
For $n \in \mathbb{N}$, $H_n = \sum_{k=1}^{n} \tfrac{1}{k}$, with $H_0 = 0$.
\end{definition}

\begin{definition}[Euler--Mascheroni constant]
$\gamma = \lim_{n\to\infty}(H_n - \ln n)$; the limit exists since $n \mapsto H_n - \ln n$ is decreasing and bounded below.
\end{definition}

\begin{definition}[Standard approximants]
For $n \in \mathbb{N}$,
\[
s_n = H_n - \ln(n+1), \qquad s'_n = H_n - \ln n,
\]
with the convention $s'_0 = H_0 = 0$. We call $s_n$ the \emph{lower} and $s'_n$ the \emph{upper} approximant. (Formally: \texttt{eulerMascheroniSeq} and \texttt{eulerMascheroniSeq'}.)
\end{definition}

\begin{definition}[Integer linear form]
For $x \in \mathbb{R}$, $q \in \mathbb{N}$, $p \in \mathbb{Z}$, the \emph{linear form} is $L(q,p;x) = q\,x - p$.
\end{definition}

\begin{definition}[Irrationality]
$x \in \mathbb{R}$ is \emph{irrational} if $x \notin \mathbb{Q}$.
\end{definition}

\section{The irrationality engine}

\subsection{The rational floor}
\begin{lemma}[Nonzero-integer floor]\label{lem:floor}
Let $x = a/b$ with $b \in \mathbb{N}_{\geq 1}$, $a \in \mathbb{Z}$. For every $q \in \mathbb{N}$, $p \in \mathbb{Z}$, $\;q x - p = (qa - pb)/b$. If $qx - p \neq 0$ then $qa - pb$ is a nonzero integer, so $|qx - p| \geq 1/b$.
\end{lemma}
\begin{proof}
Substitute $x = a/b$; $qa - pb \in \mathbb{Z}$, and a nonzero integer has absolute value at least $1$.
\end{proof}

\subsection{Sufficiency}
\begin{theorem}[$\varepsilon$-form, sufficiency]\label{thm:B}
Let $x \in \mathbb{R}$. If for every $\varepsilon > 0$ there exist $q \geq 1$, $p$ with $0 < |q x - p| < \varepsilon$, then $x$ is irrational.
\end{theorem}
\begin{proof}
Contrapose. If $x = p_0/q_0$ in lowest terms, Lemma~\ref{lem:floor} gives $|qx - p| \geq 1/q_0$ for all nonzero forms. Taking $\varepsilon = 1/q_0$ contradicts the hypothesis. Hence $x$ is irrational.
\end{proof}

\begin{theorem}[Sequence form]\label{thm:A}
Let $x \in \mathbb{R}$ and suppose $q : \mathbb{N} \to \mathbb{N}$, $p : \mathbb{N} \to \mathbb{Z}$ satisfy $q_n x - p_n \neq 0$ for all $n$ and $q_n x - p_n \to 0$. Then $x$ is irrational.
\end{theorem}
\begin{proof}
Contrapose: if $x = a/b$ rational, Lemma~\ref{lem:floor} gives $|q_n x - p_n| \geq 1/b > 0$ for all $n$, contradicting $q_n x - p_n \to 0$.
\end{proof}

\subsection{Necessity via Dirichlet}
\begin{theorem}[$\varepsilon$-form, necessity]\label{thm:C}
If $x$ is irrational, then for every $\varepsilon > 0$ there exist $q \geq 1$, $p \in \mathbb{Z}$ with $0 < |q x - p| < \varepsilon$.
\end{theorem}
\begin{proof}
Fix $\varepsilon > 0$ and choose $N$ with $1/(N+1) < \varepsilon$. By Dirichlet's approximation theorem there is $k \geq 1$ with $|k x - \round(kx)| \leq 1/(N+1) < \varepsilon$. Set $q = k$, $p = \round(kx)$. If $qx - p = 0$ then $x = p/q \in \mathbb{Q}$, a contradiction; hence $0 < |qx - p| < \varepsilon$.
\end{proof}

\begin{corollary}[Biconditional]\label{cor:bicond}
$x$ is irrational iff for every $\varepsilon > 0$ there exist $q \geq 1$, $p$ with $0 < |qx - p| < \varepsilon$. (Formally \texttt{irrational\_iff\_forall\_eps\_linear\_form}; at $\gamma$, \texttt{irrational\_eulerMascheroniConstant\_iff}.)
\end{corollary}

\section{Effective bracketing of $\gamma$}

\subsection{The sandwich}
From monotonicity of $n \mapsto H_n - \ln n$ and $1/(n+1) < \int_n^{n+1} dt/t < 1/n$, for all $n \geq 1$,
\begin{equation}\label{eq:sandwich}
s_n \;<\; \gamma \;<\; s'_n.
\end{equation}

\subsection{Exact width}
\begin{theorem}[Bracket width]\label{thm:D}
For all $n \geq 1$, $\; s'_n - s_n = \ln(n+1) - \ln n = \ln\!\bigl(1 + 1/n\bigr).$
\end{theorem}
\begin{proof}
For $n \geq 1$, $s'_n - s_n = (H_n - \ln n) - (H_n - \ln(n+1)) = \ln(n+1) - \ln n$; the harmonic terms cancel and $\ln(n+1) - \ln n = \ln((n+1)/n)$.
\end{proof}

\subsection{Effective error bounds}
\begin{theorem}[Lower error]\label{thm:E}
For all $n \geq 1$, $\;\gamma - s_n < \ln(n+1) - \ln n$.
\end{theorem}
\begin{proof}
By \eqref{eq:sandwich}, $\gamma < s'_n$, so $\gamma - s_n < s'_n - s_n$; apply Theorem~\ref{thm:D}.
\end{proof}

\begin{theorem}[Upper error]\label{thm:F}
For all $n \geq 1$, $\;s'_n - \gamma < \ln(n+1) - \ln n$.
\end{theorem}
\begin{proof}
By \eqref{eq:sandwich}, $s_n < \gamma$, so $s'_n - \gamma < s'_n - s_n$; apply Theorem~\ref{thm:D}.
\end{proof}

\begin{theorem}[Two-sided absolute error]\label{thm:G}
For all $n \geq 1$, $\;|s_n - \gamma| < \ln(n+1) - \ln n$.
\end{theorem}
\begin{proof}
By \eqref{eq:sandwich}, $s_n < \gamma$, so $|s_n - \gamma| = \gamma - s_n$; apply Theorem~\ref{thm:E}.
\end{proof}

\subsection{Rate analysis}
Since $\ln(1 + 1/n) = \tfrac1n - \tfrac{1}{2n^2} + O(n^{-3})$, the width is $\Theta(1/n)$: forcing error below $10^{-d}$ needs $n \approx 10^d$. This is \emph{sub-geometric}, in contrast with the $\rho^n$ ($\rho<1$) decay of the constructions for $e$ and $\zeta(3)$.

\section{The obstruction, made precise}
The engine (Theorem~\ref{thm:A}, Corollary~\ref{cor:bicond}) consumes \emph{integer} data: nonzero forms $q_n \gamma - p_n$ with $q_n \in \mathbb{N}_{\geq 1}$ tending to $0$. The harmonic bracket supplies $s_n, s'_n$ converging to $\gamma$, yet:
\begin{enumerate}
  \item \textbf{Transcendental endpoints.} $s_n = H_n - \ln(n+1)$ and $s'_n = H_n - \ln n$ are not rational: although $H_n \in \mathbb{Q}$, the subtracted logarithm is transcendental, so no integer $q_n$ forces an integer multiple. The bracket therefore presents no clean form $q_n \gamma - p_n$.
  \item \textbf{Sub-geometric speed.} The width $\Theta(1/n)$ is too slow for the quantitative refinements the engine needs.
\end{enumerate}
These facts explain, rigorously, why the most natural family of approximations cannot, even in principle, drive an irrationality proof of $\gamma$.

\section{Algorithms}

\subsection{Effective enclosure of $\gamma$}
\textbf{Input:} precision $\delta > 0$. \textbf{Output:} rational $[\ell,u]\ni\gamma$ with $u-\ell<\delta$.
\begin{enumerate}
  \item Choose $n$ with $\ln(1+1/n) < \delta$, e.g. $n = \lceil 1/(e^\delta - 1)\rceil$.
  \item Compute $H_n = \sum_{k=1}^n 1/k$ exactly in $\mathbb{Q}$.
  \item Interval-bound $L \leq \ln n \leq L'$ and $M \leq \ln(n+1) \leq M'$.
  \item Return $\ell = H_n - M'$, $u = H_n - L$.
\end{enumerate}
Cost: $O(1/\delta)$ rational additions plus two interval logarithms---the sub-geometric price.

\subsection{Engine certificate checker}
\textbf{Input:} triples $(q_i,p_i,b_i)$ claiming $|q_i x - p_i| < b_i$, $q_i \geq 1$, $b_i \to 0$.
\begin{enumerate}
  \item Verify $q_i \geq 1$ and $q_i x - p_i \neq 0$ for each $i$.
  \item Verify $\inf_i b_i = 0$.
  \item If so for a genuine sequence, conclude irrationality by Theorem~\ref{thm:A}.
\end{enumerate}

