function ADMITS_SMALL_FORM(x, eps, q_max):
    best <- None ; best_val <- eps
    for q in 1 .. q_max:
        p <- round(q * x)
        val <- |q*x - p|
        if 0 < val < best_val:
            best_val <- val ; best <- (q, p)
    return best        # None means no form below eps (rational floor)
